import ast,json,hashlib,importlib.util
from pathlib import Path
r=json.load(open('/tmp/r001.json'))
p=json.loads(Path('proposal.json').read_text())
def validate(v,s,path='"'$'"'):
 t=s.get('type')
 types={'object':dict,'array':list,'string':str,'boolean':bool,'number':(float,int),'integer':int}
 if t: assert isinstance(v,types[t]),(path,t,type(v))
 if 'const' in s: assert v==s['const'],path
 if 'enum' in s: assert v in s['enum'],path
 if isinstance(v,str): assert len(v)>=s.get('minLength',0),path
 if isinstance(v,list):
  assert len(v)>=s.get('minItems',0),path
  for i,x in enumerate(v): validate(x,s.get('items',{}),path+'['+str(i)+']')
 if isinstance(v,dict):
  assert set(s.get('required',[]))<=set(v),path
  props=s.get('properties',{})
  if s.get('additionalProperties') is False: assert set(v)<=set(props),(path,set(v)-set(props))
  for k,x in v.items():
   if k in props: validate(x,props[k],path+'.'+k)
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert set(p['study']['evidence_refs'])<=set(r['context']['allowed_observation_ids'])
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4
assert any(x['role']=='candidate' for x in p['variants'])
assert len({x['name'] for x in p['variants']})==len(p['variants'])
assert len({x['file'] for x in p['variants']})==len(p['variants'])
ancestor=ast.parse(Path('history_g2_r0014_local_product.py').read_text())
parent_class=next(n for n in ancestor.body if isinstance(n,ast.ClassDef))
parent_methods={n.name:n for n in parent_class.body if isinstance(n,ast.FunctionDef)}
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib'}
reference_ast=None
for v in p['variants']:
 path=Path(v['file']);assert path.name==v['file'] and path.suffix=='.py'
 source=path.read_text();tree=ast.parse(source);compile(source,str(path),'exec')
 for n in ast.walk(tree):
  if isinstance(n,ast.Import): assert all(a.name.split('.')[0] in allowed for a in n.names)
  if isinstance(n,ast.ImportFrom): assert n.module.split('.')[0] in allowed and n.level==0
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name): assert n.func.id not in {'open','exec','eval','__import__','compile','input'},n.func.id
 config=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
 assert ast.literal_eval(config.value)==v['config']
 cls=next(n for n in tree.body if isinstance(n,ast.ClassDef))
 methods={n.name:n for n in cls.body if isinstance(n,ast.FunctionDef)}
 changed={'__init__','_context_from_counts','diagnostics'}
 for name,node in parent_methods.items():
  if name not in changed: assert ast.dump(node)==ast.dump(methods[name]),(v['name'],name)
 # Every nn allocation/init call must match parent in count and order.
 def nn_calls(method):
  return [ast.dump(n) for n in ast.walk(method) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute) and isinstance(n.func.value,ast.Name) and n.func.value.id=='nn']
 assert nn_calls(methods['__init__'])==nn_calls(parent_methods['__init__'])
 # All variants identical modulo literal CONFIG.
 config.value=ast.Constant(value=None)
 normalized=ast.dump(tree)
 if reference_ast is None: reference_ast=normalized
 else: assert normalized==reference_ast
 print(v['name'],'syntax/source/import/lineage OK','sha256',hashlib.sha256(source.encode()).hexdigest())
print('study schema, evidence IDs, standalone module contracts, four-cell identity checks passed')
print('Torch available:',importlib.util.find_spec('torch') is not None)
PY"

